import { createHmac } from 'node:crypto'
import { parseBookingHttpInput } from './booking-http.ts'
import {
  assertBookingContactEmail, bookingIdentityScope, BookingRateLimitedError,
} from './booking-identity.ts'
import type { VerifiedBookingActor, BookingWriteResult } from './submit-authenticated-booking.ts'
import type { BookingRequest } from './booking-request.ts'

/**
 * A guest retry token is a cryptographically random UUIDv4 generated by the
 * client once for a booking intent, not a user ID or a session identifier.
 * The keyed scope keeps public tokens out of the stored scope and separates
 * anonymous attempts from all authenticated account scopes.
 */
const GUEST_RETRY_UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i

export function guestBookingScope(key: string, secret: string | undefined): string {
  if (!GUEST_RETRY_UUID.test(key)) throw new RangeError('Guest booking requires a random UUIDv4 retry key')
  if (typeof secret !== 'string' || secret.length < 32) {
    throw new Error('Guest booking secret is unavailable')
  }
  return 'guest:' + createHmac('sha256', secret).update('booking-guest-v1:').update(key.toLowerCase()).digest('hex')
}

/**
 * Transport-independent booking write boundary. Authenticated users retain
 * account-scoped idempotency and contact-email matching. Guests use an
 * unguessable, non-account scope. Caller data never supplies roles or IDs.
 */
export async function submitBooking<T>(input: {
  body: unknown
  idempotencyKey: string | null
  actor: VerifiedBookingActor | null
  allowed: boolean
  guestSecret: string | undefined
  create: (request: BookingRequest, scope: string, key: string) => Promise<BookingWriteResult<T>>
}): Promise<BookingWriteResult<T>> {
  if (!input.allowed) throw new BookingRateLimitedError()
  const parsed = parseBookingHttpInput(input.body, input.idempotencyKey)
  let scope: string
  if (input.actor) {
    scope = bookingIdentityScope(input.actor)
    assertBookingContactEmail(input.actor.email, parsed.request.customerEmail)
  } else {
    scope = guestBookingScope(parsed.idempotencyKey, input.guestSecret)
  }
  return input.create(parsed.request, scope, parsed.idempotencyKey)
}
